import type { Metadata } from "next";
import localFont from "next/font/local";
import "./globals.css";
import { Toaster } from "@/components/ui/Toaster";
import RootLayoutClient from "@/components/layout/RootLayoutClient";
import LiveMetricsWidget from "@/components/common/LiveMetricsWidget";
import IntlProviderWithFallback from "@/components/layout/IntlProviderWithFallback";
import { getLocale, getMessages, getTranslations } from "next-intl/server";
import { BRAND } from "@/constants/brand";

// Self-hosted so the Docker build never has to reach Google Fonts: Turbopack
// leaves every @font-face unresolved when fonts.googleapis.com is unreachable
// from the build container, which fails `next build`.
const inter = localFont({
  src: [{ path: "./fonts/InterVariable.woff2", weight: "100 900", style: "normal" }],
  display: "swap",
  variable: "--font-sans",
  fallback: ["system-ui", "Segoe UI", "sans-serif"],
});


export async function generateMetadata(): Promise<Metadata> {
  const locale = await getLocale();
  const t = await getTranslations({ locale, namespace: 'Metadata' });
  const tagline = t('tagline');
  const description = t('description');
  const keywords = t.raw('keywords') as string[];
  const title = `${BRAND.name} - ${tagline}`;

  return {
    metadataBase: new URL(BRAND.domain),
    title: {
      default: title,
      template: `%s | ${BRAND.name}`,
    },
    description,
    keywords,
    authors: [{ name: `${BRAND.name} Team` }],
    creator: BRAND.name,
    publisher: BRAND.name,
    alternates: {
      canonical: '/',
    },
    openGraph: {
      title,
      description,
      siteName: BRAND.name,
      url: BRAND.domain,
      type: 'website',
      locale: locale === 'en' ? 'en_US' : 'vi_VN',
      images: [
        {
          url: BRAND.assets.logo512,
…
        },
      ],
    },
…
  };
}

